    "license": "CC BY-SA 4.0",
    "english": "The Great Wall is a vast military defence system built by successive Chinese dynasties against northern nomads, totalling over 20,000 kilometres — hence 'the Ten-thousand-li Wall'. Most of the wall we see today dates from the Ming dynasty. Listed as a UNESCO World Heritage Site in 1987, it is also China's most famous cultural symbol.",
